subscription IssueViewerSubscriptionTimelineSubscription(
  $issueId: ID!
  $skip: Int
) {
  issueUpdated(id: $issueId) {
    issueTimelineUpdated {
      timelineItems(skip: $skip, first: 10, visibleEventsOnly: true) {
        totalCount
        edges {
          node {
            __typename
            ...SubscribedEvent
            ...UnsubscribedEvent
            ...MentionedEvent
            ...IssueComment_issueComment
            ...ReactionViewerRelayGroups
            ...ClosedEvent
            ...ReopenedEvent
            ...LockedEvent
            ...UnlockedEvent
            ...PinnedEvent
            ...UnpinnedEvent
