            ...RenamedTitleEvent
            ...UnlabeledEvent
            ...UnassignedEvent
            ...AssignedEvent
            ...CommentDeletedEvent
            ...UserBlockedEvent
            ...MilestonedEvent
            ...DemilestonedEvent
            ...CrossReferencedEvent
            ...ReferencedEvent
            ...ConnectedEvent
            ...TransferredEvent
            ...DisconnectedEvent
            ...MarkedAsDuplicateEvent
            ...UnmarkedAsDuplicateEvent
            ...ConvertedToDiscussionEvent
            ...AddedToProjectV2Event
            ...RemovedFromProjectV2Event
            ...ProjectV2ItemStatusChangedEvent
            ...ConvertedFromDraftEvent
            ...SubIssueAddedEvent
            ...SubIssueRemovedEvent
            ...ParentIssueAddedEvent
            ...ParentIssueRemovedEvent
            ...BlockedByAddedEvent
            ...BlockedByRemovedEvent
            ...BlockingAddedEvent
            ...BlockingRemovedEvent
            ...IssueTypeAddedEvent
            ...IssueTypeRemovedEvent
            ...IssueTypeChangedEvent
            ...IssueFieldChangedEvent
            ...IssueFieldRemovedEvent
            ...IssueFieldAddedEvent
            ...IssueCommentPinnedEvent
            ...IssueCommentUnpinnedEvent
            ... on Node {
              __isNode: __typename
