query useIssueFormSecondaryQuery(
  $id: ID!
) {
  node(id: $id) {
    __typename
    ... on Repository {
      securityPolicyUrl
      contributingFileUrl
      codeOfConductFileUrl
      supportFileUrl
      owner {
        __typename
        ... on Organization {
          pinnedIssueFields(first: 10) {
            nodes {
              __typename
              ... on IssueFieldText {
                id
                name
                dataType
                visibility
              }
              ... on IssueFieldSingleSelect {
                id
                name
                dataType
                visibility
              }
              ... on IssueFieldDate {
                id
                name
                dataType
                visibility
              }
              ... on IssueFieldNumber {
                id
                name
                dataType
                visibility
              }
              ... on Node {
                __isNode: __typename
                id
              }
            }
          }
          issueFields(first: 100) {
            nodes {
              __typename
              ... on IssueFieldText {
                id
                visibility
              }
              ... on IssueFieldSingleSelect {
                id
                visibility
              }
              ... on IssueFieldDate {
                id
                visibility
              }
              ... on IssueFieldNumber {
                id
                visibility
              }
              ... on Node {
                __isNode: __typename
                id
              }
            }
          }
        }
        id
      }
    }
    id
  }
}

