202bc6ed7ea8927c1a0ba9560f42bb32.query:
query secondaryTimelineQuery(
  $nodes: [ID!]!
) {
  nodes(ids: $nodes) {
    __typename
    ... on ReferencedEvent {
      commit {
        ...ReferencedEventVerificationStatusInner
        id
      }
    }
    id
  }
}

fragment ReferencedEventVerificationStatusInner on Commit {
  abbreviatedOid
  hasSignature
  verificationStatus
  signature {
    __typename
    signer {
      login
      avatarUrl
      id
    }
    state
    wasSignedByGitHub
    ... on SmimeSignature {
      issuer {
        commonName
        emailAddress
        organization
        organizationUnit
      }
      subject {
        commonName
        emailAddress
        organization
        organizationUnit
      }
    }
    ... on GpgSignature {
      keyId
    }
    ... on SshSignature {
      keyFingerprint
    }
