fragment TemplateList on Repository {
  id
  nameWithOwner
  issueForms {
    __typename
    filename
    ...IssueFormRow
  }
  issueTemplates {
    __typename
    filename
    ...IssueTemplateRow
  }
  isBlankIssuesEnabled
  isBlankIssuesMaintainerOverride
  isSecurityPolicyEnabled
  securityPolicyUrl
  contactLinks {
    name
    ...ExternalLinkTemplateRow
  }
  hasAnyTemplates
}

fragment TemplateListPane on Repository {
  hasIssuesEnabled
  ...TemplateList
}

fragment TemplatePickerButton on Repository {
  nameWithOwner
  hasAnyTemplates
}

