45538d05afecb94c4759f1703a7f7f06.query:
query IssueSubIssues_NestedQuery(
  $id: ID!
) {
  node(id: $id) {
    __typename
    ... on Issue {
      id
      subIssues(first: 100) {
        nodes {
          ...IssueSubIssues_InnerFragment
          id
        }
      }
    }
    id
  }
}

fragment IssueSubIssues_InnerFragment on Issue {
  id
  title
  titleHTML
  state
  url
  labels(first: 10) {
    nodes {
      id
      name
      color
    }
  }
  assignees(first: 10) {
    totalCount
    edges {
      node {
        id
        login
        avatarUrl
      }
    }
  }
  subIssuesSummary {
    total
    completed
    percentCompleted
  }
  closedByPullRequestsReferences(first: 0, includeClosedPrs: true) {
    totalCount
  }
}

b83819e3267088a514ba0c0458c33d5e.query:
query useLabelsQueryQuery(
  $owner: String!
  $repo: String!
  $labelNames: String = ""
  $count: Int = 100
) {
  repository(owner: $owner, name: $repo) {
    labels(names: $labelNames, first: $count, orderBy: {field: NAME, direction: ASC}) {
      nodes {
        id
        color
        name
        nameHTML
        description
        url
      }
    }
    id
  }
}

74cdd586b6f12a28054626de37364e0a.query:
query useIssueQueryQuery(
  $owner: String!
  $name: String!
  $number: Int!
) {
  repository(owner: $owner, name: $name) {
    issue(number: $number) {
      ...useIssueQueryIssueContent
      id
    }
    id
  }
}

fragment useIssueQueryIssueContent on Issue {
  id
  databaseId
  number
  title
  body
  url
  repository {
    id
    databaseId
    name
    owner {
      __typename
      login
      id
    }
    isArchived
    isCopilotAgentEnabled
    defaultBranchRef {
      name
      id
    }
  }
  assignees(first: 20) {
    nodes {
      login
      id
    }
  }
  labels(first: 20) {
    nodes {
      name
      id
    }
  }
  milestone {
    title
    id
  }
  issueType {
    name
    id
  }
  projectItems(first: 20) {
    nodes {
      id
      project {
        id
        title
      }
    }
  }
  subIssues(first: 1) {
    totalCount
  }
}

cc890d4a355bf52f7d7b18263e22f595.query:
