453f03781d915408c3c338e5d346e0be.query:
query TemplatePickerQuery(
  $owner: String!
  $repo: String!
) {
  repository(owner: $owner, name: $repo) {
    issueForms {
      __typename
      ...TemplatePickerForm
    }
    issueTemplates {
      __typename
      ...TemplatePickerTemplate
    }
    id
  }
}

fragment TemplatePickerForm on IssueForm {
