  filename
  name
  description
}

fragment TemplatePickerTemplate on IssueTemplate {
  __typename
  filename
  name
  about
}

d1d9840a47a7be6dd0ad285ce57f1c7f.query:
mutation updateIssueMutationContentOnlyMutation(
  $input: UpdateIssueInput!
) {
